PB.drawCanonicalMask=function(x,y,dir='down'){const image=C3.images.prebeta_mask;if(!image?.complete||!image.naturalWidth)return false;const map={down:0,left:1,up:3,right:1},col=map[dir]??0,sw=image.naturalWidth/4,sh=image.naturalHeight/2,flip=dir==='right';ctx.save();ctx.imageSmoothingEnabled=false;ctx.translate(Math.round(x),Math.round(y));if(flip)ctx.scale(-1,1);ctx.drawImage(image,col*sw,0,sw,sh,-18,-25,36,36);ctx.restore();return true};
drawActor=function(p,x,y,moving=false){const style=p.style||'franco',row=PB.heroRows[style],rolling=G?.active===style&&Combat10?.dashTime>0;if(rolling&&row!==undefined&&C3.images.prebeta_roll?.complete&&C3.images.prebeta_roll.naturalWidth){const image=C3.images.prebeta_roll,sw=image.naturalWidth/6,sh=image.naturalHeight/6,phase=clamp(1-Combat10.dashTime/Math.max(.01,TUNING10.dash.duration),0,.999),frame=Math.floor(phase*6);ctx.save();ctx.imageSmoothingEnabled=false;ctx.drawImage(image,frame*sw,row*sh,sw,sh,Math.round(x-34),Math.round(y-66),68,68);ctx.restore();return}if((style==='synth'||style==='percussion')&&C3.images.prebeta_run_v2?.complete&&C3.images.prebeta_run_v2.naturalWidth){const image=C3.images.prebeta_run_v2,dir=PB.directionIndex[p.dir||'down']||0,frame=moving?Math.floor(tick*(G?.isRunning10?11:7))%3:0,sw=image.naturalWidth/12,sh=image.naturalHeight/2,rowRun=style==='synth'?0:1;ctx.save();ctx.imageSmoothingEnabled=false;ctx.drawImage(image,(dir*3+frame)*sw,rowRun*sh,sw,sh,Math.round(x-ACTOR_W/2),Math.round(y-ACTOR_H+11),ACTOR_W,ACTOR_H);ctx.restore();return}if(G.flags.masks&&(style==='franco'||style==='ryuchi')){const masked=G.flags.masks;G.flags.masks=false;PB_actorBase(p,x,y,moving);G.flags.masks=masked;PB.drawCanonicalMask(x,y-33,p.dir||'down');return}PB_actorBase(p,x,y,moving)};

const PB_dialogueBase=advanceDialogue;
advanceDialogue=function(){PB_dialogueBase();if(mode!=='dialogue')return;const who=($('speaker')?.textContent||'').toLocaleLowerCase('pt-BR'),portrait=$('portrait');let collab=who.includes('belga')||who.includes('bento')||who.includes('maia')?0:who.includes('colli')||who.includes('nilo')||who.includes('ciro')?1:who.includes('mazza')||who.includes('nara')?2:null;if(collab!==null){const image=C3.images.prebeta_collabs;if(!image?.complete||!image.naturalWidth)return;const sw=image.naturalWidth/3,sh=image.naturalHeight/2,c=document.createElement('canvas');c.width=96;c.height=96;const q=c.getContext('2d');q.imageSmoothingEnabled=false;q.drawImage(image,collab*sw,sh,sw,sh,0,0,96,96);portrait.src=c.toDataURL('image/png');return}if(who.includes('dney')||who.includes('vega')){const image=C3.images.prebeta_dney;if(!image?.complete||!image.naturalWidth)return;const sw=image.naturalWidth/4,sh=image.naturalHeight/3,c=document.createElement('canvas');c.width=96;c.height=96;const q=c.getContext('2d');q.imageSmoothingEnabled=false;q.drawImage(image,0,sh*2,sw,sh,0,0,96,96);portrait.src=c.toDataURL('image/png');return}let cell=null;if(who.includes('sintet'))cell=[2,1];else if(who.includes('percuss'))cell=[3,1];else if(who.includes('arque')||who.includes('outro franco'))cell=[0,1];else if(who.includes('espada')||who.includes('katana')||who.includes('outro ryuchi'))cell=[1,1];else if(who.includes('franco'))cell=[G?.flags?.masks?2:0,0];else if(who.includes('ryuchi'))cell=[G?.flags?.masks?3:1,0];if(!cell)return;const image=C3.images.prebeta_portraits_v2;if(!image?.complete||!image.naturalWidth)return;const sw=image.naturalWidth/4,sh=image.naturalHeight/3,sy=cell[1]*sh+Math.max(0,(sh-sw)*.13),c=document.createElement('canvas');c.width=96;c.height=96;const q=c.getContext('2d');q.imageSmoothingEnabled=false;q.drawImage(image,cell[0]*sw,sy,sw,sw,0,0,96,96);portrait.src=c.toDataURL('image/png')};

function c3NpcPose(n){let dir=n.dir||'down';if(G&&Number.isFinite(n.x)&&Number.isFinite(n.y)){const dx=G.x-n.x,dy=G.y-n.y;if(Math.hypot(dx,dy)<5.5)dir=Math.abs(dx)>Math.abs(dy)?(dx<0?'left':'right'):(dy<0?'up':'down')}return {dir,frame:Math.floor(tick*2.1+(Number(n.x)||0)*.37+(Number(n.y)||0)*.19)%2}}
const C3_npcBase=drawDetailedNPC;
drawDetailedNPC=function(n,x,y){const pose=c3NpcPose(n),group={down:0,left:1,up:2,right:3}[pose.dir]||0;if(n.id==='c3_alt_final'){drawActor({style:'alt',dir:pose.dir},x,y,false);return}if(n.id==='c3_katana_final'){drawActor({style:'katana',dir:pose.dir},x,y,false);return}const central=n.id==='c3_maia'?0:n.id==='c3_ciro'?2:(n.id==='c3_nara'||n.id==='c3_nara_canal')?1:null;if(central!==null&&c3SheetSprite(C3.images.prebeta_collabs_move,group*2+pose.frame,central,8,3,x,y,56,70))return;if(n.id==='c3_vega'&&c3SheetSprite(C3.images.prebeta_dney,group,pose.frame,4,3,x,y,56,70))return;const collaborator=n.spriteKey==='bento'?0:n.spriteKey==='nilo'?1:null;if(collaborator!==null&&c3SheetSprite(C3.images.prebeta_collabs,collaborator,0,3,2,x,y,56,70))return;if((n.id==='c3_synth_npc'||n.id==='c3_percussion_npc')&&C3.images.prebeta_run_v2?.complete){const row=n.id==='c3_synth_npc'?0:1,frame=group*3+pose.frame;if(c3SheetSprite(C3.images.prebeta_run_v2,frame,row,12,2,x,y,ACTOR_W,ACTOR_H))return}const movement={c3_resident:'sprite_resident_a',c3_resident_b:'sprite_resident_b',c3_canal_worker:'sprite_canal_worker',c3_plant_operator:'sprite_plant_operator'};if(movement[n.id]&&c3MoveSprite(C3.images[movement[n.id]],x,y,68,82,pose.dir,pose.frame))return;C3_npcBase(n,x,y)};

