showDefeat=function(){if(!G?.c3?.started||!C3.AREAS.includes(G.area))return C3_defeatBase();const cpName=checkpointName(G.checkpoint?.id||'c3_district'),finalFight=bossActor?.id==='c3_silence';bossActor=null;battle=null;C3.hazards=[];C3.finalPending=false;C3.phraseInput=[];hostileShots=[];projectiles=[];combatFX.length=0;$('actionHUD').classList.add('hidden');attackHeld=false;openOverlay(`<div class="eyebrow" style="text-align:center">CAPÍTULO 03 · A FREQUÊNCIA SE PARTIU</div><h2 class="defeat-title">AINDA DÁ PARA RECOMEÇAR</h2><p style="text-align:center">A formação retorna à última ressonância sem perder aliados, relíquias ou a frase do Contratempo.</p><div class="checkpoint-panel"><strong>◆ CHECKPOINT: ${cpName}</strong>${finalFight?'A arena será reconstruída e uma nova tentativa escolherá cinco padrões do repertório de sete.':'O encontro recomeça limpo, com a equipe recuperada.'}</div><div class="row" style="justify-content:center"><button class="action strong" id="retryCheckpoint">↻ TENTAR NOVAMENTE</button><button class="action" id="c3RestCheckpoint">DESCANSAR NO CHECKPOINT</button></div>`);$('retryCheckpoint').onclick=()=>finalFight?C3.retryFinal():restoreCheckpoint();$('c3RestCheckpoint').onclick=()=>restoreCheckpoint({c3Rest:true});save(true)};

