window.addEventListener('keydown',e=>{if(e.key==='Escape'&&C3.phraseOrigin==='final'&&$('overlay')&&!$('overlay').classList.contains('hidden')){e.preventDefault();e.stopImmediatePropagation();toast('A ÚLTIMA FREQUÊNCIA PRECISA COMEÇAR')}},true);

/* Controle PlayStation e coop local.
   A formação física inspirada nos JRPGs mantém o líder como âncora da câmera;
   o segundo controle assume um aliado real, com movimento, HP e ações próprios. */
C3.pad={pads:[],previous:new Map(),lastFrame:0,raf:0,focusIndex:0};
C3.coop={x:0,y:0,dir:'down',area:'',member:null,cool:0,skill:0,advanced:0,signature:0,dash:0,dashCD:0,invuln:0,hit:0,contact:0,moving:false};
C3.padPressed=(pad,index)=>!!pad?.buttons?.[index]?.pressed;
C3.padEdge=function(pad,index){const before=C3.pad.previous.get(pad.index)||[];return C3.padPressed(pad,index)&&!before[index]};
C3.padAxis=function(pad,index){const raw=pad?.axes?.[index]||0;return Math.abs(raw)<.22?0:Math.sign(raw)*(Math.abs(raw)-.22)/.78};
C3.padDirection=function(pad){let x=C3.padAxis(pad,0),y=C3.padAxis(pad,1);if(C3.padPressed(pad,14))x=-1;if(C3.padPressed(pad,15))x=1;if(C3.padPressed(pad,12))y=-1;if(C3.padPressed(pad,13))y=1;const n=Math.hypot(x,y);return n>1?[x/n,y/n]:[x,y]};
C3.padPulse=function(pad,strong=.18,weak=.08,duration=90){try{pad?.vibrationActuator?.playEffect?.('dual-rumble',{duration,strongMagnitude:strong,weakMagnitude:weak})}catch(_){}}
C3.coopMember=function(){if(!G)return null;const available=partyMembers().filter(id=>id!==G.active&&(G.hp?.[id]||0)>0);if(!available.length)return null;if(!available.includes(C3.coop.member))C3.coop.member=available[0];return C3.coop.member};
C3.coopActive=function(){return !!(G&&current&&C3.pad.pads[1]&&C3.coopMember())};
C3.syncCoop=function(force=false){if(!C3.coopActive())return;const c=C3.coop;if(force||c.area!==G.area||!Number.isFinite(c.x)||Math.hypot(c.x-G.x,c.y-G.y)>9.5){c.x=G.x-.65;c.y=G.y+.55;c.dir=G.dir;c.area=G.area;c.dash=0;c.invuln=1}}
C3.coopVector=function(){return ({up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]})[C3.coop.dir]||[0,1]};
C3.coopMove=function(pad,dt){const c=C3.coop;if(!C3.coopActive()||!['walk','action'].includes(mode)){c.moving=false;return}C3.syncCoop();let [dx,dy]=C3.padDirection(pad),n=Math.hypot(dx,dy);if(c.dash>0&&n<=.08){[dx,dy]=c.dashDir||C3.coopVector();n=1}c.moving=n>.08;if(!c.moving)return;if(Math.abs(dx)>Math.abs(dy))c.dir=dx<0?'left':'right';else c.dir=dy<0?'up':'down';const running=C3.padPressed(pad,6)||C3.padPressed(pad,10)||n>.82,speed=(running?5.25:3.65)*(c.dash>0?1.75:1),step=speed*dt,nx=c.x+dx*step,ny=c.y+dy*step,max=7.25;let tx=tileWalkable(current,nx,c.y)?nx:c.x,ty=tileWalkable(current,tx,ny)?ny:c.y;if(Math.hypot(tx-G.x,ty-G.y)<=max){c.x=tx;c.y=ty}else{const a=Math.atan2(c.y-G.y,c.x-G.x);c.x=G.x+Math.cos(a)*max;c.y=G.y+Math.sin(a)*max}lastStep=Math.min(lastStep,.12)};
C3.coopTargets=function(range=2.45,front=.02){const c=C3.coop,d=C3.coopVector();return meleeCandidates().filter(e=>{const x=e.x-c.x,y=e.y-c.y,dist=Math.hypot(x,y);return dist<range&&(x*d[0]+y*d[1])/Math.max(.01,dist)>front}).sort((a,b)=>Math.hypot(a.x-c.x,a.y-c.y)-Math.hypot(b.x-c.x,b.y-c.y))};
C3.coopAttack=function(pad){if(!C3.coopActive()||!['walk','action'].includes(mode)||C3.coop.cool>0)return;if(mode==='walk')engage();const c=C3.coop,id=C3.coopMember(),ranged=['alt','synth'].includes(id),targets=C3.coopTargets(ranged?5.4:2.65,ranged?.52:-.12),limit=ranged?2:3,damage=id==='percussion'?15:id==='katana'?17:ranged?13:14;targets.slice(0,limit).forEach(e=>hitEnemy(e,damage,id==='percussion'?.38:.2,0));c.cool=id==='percussion'?.32:ranged?.38:.26;addCombatFX(c.x+C3.coopVector()[0],c.y+C3.coopVector()[1],id==='synth'?'pulse':'strike',ranged?1.8:1.25);playTone(id==='percussion'?147:id==='synth'?330:220,.1,id==='synth'?'sine':'triangle',.06);G.resonance=Math.min(100,G.resonance+4);C3.padPulse(pad,.16,.1,70);updateActionHUD()};
C3.coopSkill=function(pad){if(!C3.coopActive()||!['walk','action'].includes(mode)||C3.coop.skill>0)return;if(mode==='walk')engage();const c=C3.coop,id=C3.coopMember(),radius=id==='synth'?4.4:3.45,damage=id==='percussion'?28:id==='synth'?22:24;for(const e of meleeCandidates())if(Math.hypot(e.x-c.x,e.y-c.y)<radius)hitEnemy(e,damage,.62,0);c.skill=4.2;addCombatFX(c.x,c.y,id==='percussion'?'duo':'pulse',radius);playTone(id==='percussion'?98:392,.26,id==='synth'?'sine':'square',.07);C3.padPulse(pad,.32,.2,130);updateActionHUD()};
C3.coopAdvanced=function(pad){if(!C3.coopActive()||mode!=='action'||C3.coop.advanced>0)return;const c=C3.coop,id=C3.coopMember(),d=C3.coopVector();for(const e of meleeCandidates()){const x=e.x-c.x,y=e.y-c.y,forward=x*d[0]+y*d[1],side=Math.abs(x*d[1]-y*d[0]);if((forward>0&&forward<6&&side<1.35)||Math.hypot(x,y)<2)hitEnemy(e,id==='katana'?39:34,1,0)}c.advanced=6.5;c.invuln=.55;addCombatFX(c.x,c.y,'duo',4);screenShake=Math.max(screenShake,.28);C3.padPulse(pad,.48,.3,180);updateActionHUD()};
C3.coopSignature=function(pad){if(!C3.coopActive()||mode!=='action'||C3.coop.signature>0)return;if(G.resonance<40)return toast('JOGADOR 2 · 40 DE RESSONÂNCIA NECESSÁRIOS');G.resonance-=40;const c=C3.coop;for(const e of meleeCandidates())if(Math.hypot(e.x-c.x,e.y-c.y)<5)hitEnemy(e,44,1.3,0);for(const id of partyMembers())if(G.hp[id]>0)G.hp[id]=Math.min(G.maxhp[id],G.hp[id]+6);c.signature=7;c.invuln=.75;addCombatFX(c.x,c.y,'duo',5);screenShake=.45;C3.padPulse(pad,.7,.45,260);updateActionHUD()};
C3.coopDodge=function(pad){const c=C3.coop;if(!C3.coopActive()||mode!=='action'||c.dashCD>0)return;c.dashDir=C3.padDirection(pad);if(Math.hypot(...c.dashDir)<.08)c.dashDir=C3.coopVector();c.dash=.30;c.dashCD=.72;c.invuln=.48;addCombatFX(c.x,c.y,'dodge',.8);C3.padPulse(pad,.12,.2,80)};
C3.cycleCoop=function(){if(!G)return;const list=partyMembers().filter(id=>id!==G.active&&(G.hp?.[id]||0)>0);if(list.length<2)return toast('JOGADOR 2 · NÃO HÁ OUTRO ALIADO ESCALADO');const i=Math.max(0,list.indexOf(C3.coopMember())),chosen=list[(i+1)%list.length];C3.coop.member=chosen;G.formation=[G.active,chosen,...partyMembers().filter(id=>id!==G.active&&id!==chosen)].slice(0,3);C3.coop.invuln=.5;toast('JOGADOR 2 · '+(labels10?.[chosen]||chosen).toUpperCase());C3.updatePadStatus()};
C3.damageCoop=function(amount){const c=C3.coop,id=C3.coopMember();if(!id||c.invuln>0||mode!=='action')return;G.hp[id]=Math.max(0,G.hp[id]-amount);c.invuln=.8;c.hit=.35;screenShake=Math.max(screenShake,.2);addCombatFX(c.x,c.y,'hurt',1);C3.padPulse(C3.pad.pads[1],.35,.25,140);if(G.hp[id]<=0){toast('JOGADOR 2 · '+(labels10?.[id]||id).toUpperCase()+' SAIU DE COMBATE');c.member=null;C3.syncCoop(true)}updateActionHUD()};
C3.updateCoopCombat=function(dt){const c=C3.coop;if(!C3.coopActive())return;for(const key of ['cool','skill','advanced','signature','dash','dashCD','invuln','hit','contact'])c[key]=Math.max(0,(c[key]||0)-dt);if(mode!=='action')return;for(let i=hostileShots.length-1;i>=0;i--)if(Math.hypot(hostileShots[i].x-c.x,hostileShots[i].y-c.y)<.68){const shot=hostileShots[i];hostileShots.splice(i,1);C3.damageCoop(shot.damage||8)}if(c.contact<=0){const foe=meleeCandidates().find(e=>e.hp>0&&Math.hypot(e.x-c.x,e.y-c.y)<.82);if(foe){C3.damageCoop(Math.max(5,Math.round((foe.power||8)*.65)));c.contact=.72}}};
C3.focusPadMenu=function(delta=0){const scope=!$('overlay')?.classList.contains('hidden')?$('overlay'):$('start'),buttons=[...scope.querySelectorAll('button:not([disabled])')].filter(b=>b.offsetParent!==null);if(!buttons.length)return null;let i=buttons.indexOf(document.activeElement);if(i<0)i=C3.pad.focusIndex%buttons.length;else i=(i+delta+buttons.length)%buttons.length;C3.pad.focusIndex=i;buttons[i].focus();return buttons[i]};
C3.handleMenuPad=function(pad){if(C3.padEdge(pad,12)||C3.padEdge(pad,14))C3.focusPadMenu(-1);if(C3.padEdge(pad,13)||C3.padEdge(pad,15))C3.focusPadMenu(1);if(C3.padEdge(pad,0))(C3.focusPadMenu(0)||document.activeElement)?.click?.();if(C3.padEdge(pad,1)&&mode==='overlay')closeOverlay()};
C3.handlePrimaryPad=function(pad){const [x,y]=C3.padDirection(pad);touchDir.left=x<-.18;touchDir.right=x>.18;touchDir.up=y<-.18;touchDir.down=y>.18;runningTouch=C3.padPressed(pad,6)||C3.padPressed(pad,10)||Math.hypot(x,y)>.82;if(!G||['title','overlay','rhythm'].includes(mode))return C3.handleMenuPad(pad);if(mode==='dialogue'){if(C3.padEdge(pad,0)||C3.padEdge(pad,2))advanceDialogue();return}if(C3.padEdge(pad,0))interact();if(C3.padEdge(pad,2))attackAction();if(C3.padEdge(pad,1)){if(mode==='action')dodgeAction();else openSystem()}if(C3.padEdge(pad,3))switchHero();if(C3.padEdge(pad,4))skillAction();if(C3.padEdge(pad,5))advancedSkill();if(C3.padEdge(pad,7))duoAction();if(C3.padEdge(pad,9))openSystem()};
C3.handleSecondPad=function(pad,dt){if(!C3.coopActive())return;C3.coopMove(pad,dt);if(mode==='dialogue'){if(C3.padEdge(pad,0))advanceDialogue();return}if(C3.padEdge(pad,0)){if(Math.hypot(C3.coop.x-G.x,C3.coop.y-G.y)<2.2)interact();else toast('JOGADOR 2 · APROXIME-SE DO LÍDER PARA INTERAGIR')}if(C3.padEdge(pad,2))C3.coopAttack(pad);if(C3.padEdge(pad,1))C3.coopDodge(pad);if(C3.padEdge(pad,4))C3.coopSkill(pad);if(C3.padEdge(pad,5))C3.coopAdvanced(pad);if(C3.padEdge(pad,7))C3.coopSignature(pad);if(C3.padEdge(pad,3))C3.cycleCoop()};
C3.pollControllers=function(now){const dt=Math.min(.05,Math.max(0,(now-(C3.pad.lastFrame||now))/1000));C3.pad.lastFrame=now;C3.pad.pads=[...(navigator.getGamepads?.()||[])].filter(Boolean).sort((a,b)=>a.index-b.index);const p1=C3.pad.pads[0],p2=C3.pad.pads[1];if(p1)C3.handlePrimaryPad(p1);else{touchDir.left=touchDir.right=touchDir.up=touchDir.down=false;runningTouch=false}if(p2)C3.handleSecondPad(p2,dt);C3.updateCoopCombat(dt);if(now-(C3.pad.statusAt||0)>300){C3.pad.statusAt=now;C3.updatePadStatus()}for(const p of C3.pad.pads)C3.pad.previous.set(p.index,p.buttons.map(b=>!!b.pressed));for(const index of [...C3.pad.previous.keys()])if(!C3.pad.pads.some(p=>p.index===index))C3.pad.previous.delete(index);C3.pad.raf=requestAnimationFrame(C3.pollControllers)};
C3.updatePadStatus=function(){const el=$('gamepadStatus');if(!el)return;const count=C3.pad.pads.length;el.classList.toggle('hidden',!count);if(!count)return;const member=C3.coopActive()?(labels10?.[C3.coopMember()]||C3.coopMember()):'';el.textContent=count>1&&member?'🎮 CO-OP · P2 '+member.toUpperCase():'🎮 CONTROLE 1P'};
C3.installGamepads=function(){if($('gamepadStatus'))return;const style=document.createElement('style');style.textContent='#gamepadStatus{position:fixed;left:10px;bottom:10px;z-index:9998;padding:7px 10px;border:1px solid #dbba88;background:#151222e8;color:#f4dfb4;font:700 10px monospace;letter-spacing:.06em;pointer-events:none}#gamepadStatus.hidden{display:none}button:focus{outline:2px solid #78e5eb;outline-offset:3px}';document.head.appendChild(style);const chip=document.createElement('div');chip.id='gamepadStatus';chip.className='hidden';document.body.appendChild(chip);window.addEventListener('gamepadconnected',e=>{setTimeout(()=>{C3.updatePadStatus();toast((C3.pad.pads.length>1?'CO-OP LOCAL ATIVO':'CONTROLE PLAYSTATION CONECTADO'))},80)});window.addEventListener('gamepaddisconnected',()=>setTimeout(()=>{C3.updatePadStatus();C3.coop.member=null},80));C3.pad.raf=requestAnimationFrame(C3.pollControllers)};
const C3_gamepadHelpBase=openHelp;
openHelp=function(){C3_gamepadHelpBase();const close=$('helpClose');if(!close||$('controllerHelp'))return;const info=document.createElement('div');info.id='controllerHelp';info.innerHTML='<hr class="divider"><div class="eyebrow">CONTROLE PLAYSTATION · 1 OU 2 JOGADORES</div><div class="stat"><span>Mover / correr</span><b>ANALÓGICO OU DIRECIONAL / L2</b></div><div class="stat"><span>Interagir / confirmar</span><b>✕</b></div><div class="stat"><span>Atacar / esquivar</span><b>□ / ○</b></div><div class="stat"><span>Técnicas</span><b>L1 / R1 · ESPECIAL R2</b></div><div class="stat"><span>Trocar integrante</span><b>△</b></div><div class="stat"><span>Pausa</span><b>OPTIONS</b></div><p>Com dois controles, o Jogador 1 conduz a história e a câmera. O Jogador 2 assume outro integrante escalado, luta com HP próprio e pode trocar de aliado com △. Para interagir, os dois precisam estar próximos.</p>';close.before(info)};

const C3_gamepadFollowerBase=getFollower;
getFollower=function(index){if(index===0&&C3.coopActive()){C3.syncCoop();return {x:C3.coop.x,y:C3.coop.y,dir:C3.coop.dir}}return C3_gamepadFollowerBase(index)};
const C3_gamepadActionBase=updateAction;
updateAction=function(dt){if(C3.coopActive())companionCooldown=Math.max(companionCooldown,.48);return C3_gamepadActionBase(dt)};
const C3_gamepadHazardBase=C3.fireHazard;
C3.fireHazard=function(h,e){let coopHit=false;if(C3.coopActive()){const c=C3.coop,dx=c.x-h.x,dy=c.y-h.y,d=Math.hypot(dx,dy);if(h.kind==='ring')coopHit=d<h.r;else if(h.kind==='cross')coopHit=Math.abs(dx)<h.width||Math.abs(dy)<h.width;else if(h.kind==='fan'){const a=Math.atan2(dy,dx),diff=Math.abs(Math.atan2(Math.sin(a-h.angle),Math.cos(a-h.angle)));coopHit=d<h.r&&diff<h.arc}else if(h.kind==='rain')coopHit=d<h.r;else if(h.kind==='pulse')coopHit=d>h.inner&&d<h.r}const result=C3_gamepadHazardBase(h,e);if(coopHit)C3.damageCoop(h.damage||10);return result};
pollGamepad=function(){};

window.__toriiAlphaDebug={version:13,state:()=>G?copy(G):null,previewChapter3:()=>C3.start(true),warp:(area,x=5.5,y=5.5)=>setArea(area,x,y,false),setC3:patch=>{Object.assign(G.c3,patch);C3.applyWorld();updateHUD()},startBoss:id=>id==='silence'?C3.startSilence(false):C3.startMetronome(false),finishBoss:()=>bossActor?.id==='c3_metronome'?C3.finishMetronome():bossActor?.id==='c3_silence'?C3.finishSilence():null,patterns:()=>[...C3.bossPattern]};

const C3_continueBase=continueGame;
continueGame=function(){const result=C3_continueBase();if(G?.c3?.endingPending&&!G.c3.complete)setTimeout(()=>C3.resumeEnding(),120);return result};

C3.qaState=function(stage){if(stage==='win'&&bossActor){if(bossActor.id==='c3_metronome')return C3.finishMetronome();bossActor.hp=1;return hitEnemy(bossActor,10)}if(stage==='defeat'&&bossActor)return showDefeat();if(!G?.c3?.started)C3.start(true);$('dialogue').classList.add('hidden');$('cinema').style.display='none';$('overlay').classList.add('hidden');menuOpen=false;mode='walk';Object.assign(G.c3,{metMaia:true,twoRoutesOpen:true,usinaGate:true,usinaDone:true,canalPath:true,canalDone:true,synthUnlocked:true,percussionUnlocked:true,windFlute:true,clubPhrase:[0,1,2,3],clubPhraseDone:true,horizonDrum:true,liftOpen:true,cloudPathA:true,cloudPathB:true,cloudPlatform:true});G.hp.synth=G.maxhp.synth;G.hp.percussion=G.maxhp.percussion;G.formation=['synth','percussion','katana'];G.active='synth';buildMaps();if(stage==='routes')setArea('distortion_district',31.5,28.5,false);if(stage==='metronome'){setArea('cloud_terrace',15.5,14.5,false);C3.startMetronome(false)}if(stage==='silence'){G.c3.metronomeDone=true;setArea('last_torii',13.5,13.5,false);setCheckpoint('c3_final','last_torii',13.5,13.5,true);setArea('silence_core',17.5,20.5,false);C3.startSilence(false)}if(stage==='ending'){G.c3.metronomeDone=true;G.c3.silenceDone=true;G.c3.returnHome=true;G.c3.endingPending=true;C3.returnStudio()}save(true);updateHUD()};
C3.installQA=function(){if(!new URLSearchParams(location.search).has('qa')||$('c3QAPanel'))return;const box=document.createElement('div');box.id='c3QAPanel';box.style.cssText='position:fixed;right:8px;bottom:8px;z-index:99999;display:flex;gap:4px;flex-wrap:wrap;max-width:420px;background:#100d1ddd;padding:6px;border:1px solid #d89aaf';box.innerHTML='<button class="action" data-c3qa="routes">QA ROTAS</button><button class="action" data-c3qa="metronome">QA METRÔNOMO</button><button class="action" data-c3qa="silence">QA SILÊNCIO</button><button class="action" data-c3qa="win">QA VENCER</button><button class="action" data-c3qa="defeat">QA DERROTA</button><button class="action" data-c3qa="ending">QA EPÍLOGO</button>';document.body.appendChild(box);box.querySelectorAll('[data-c3qa]').forEach(b=>b.onclick=()=>C3.qaState(b.dataset.c3qa))};

const C3_initBase=init;
init=function(){C3_initBase();document.title='Torii & Hutukara · Alpha 1.2.0 · Pré-beta';const ver=document.querySelector('#start .version');if(ver)ver.textContent='ALPHA 1.2.0 · PRÉ-BETA · TRÊS CAPÍTULOS';const build=document.querySelector('.brandbar .build');if(build)build.innerHTML='TORII & HUTUKARA<br>ALPHA 1.2.0 · PRÉ-BETA';const sub=document.querySelector('#start .sub');if(sub)sub.textContent='TRÊS CAPÍTULOS · UMA JORNADA MUSICAL · CONTROLE PLAYSTATION · CO-OP LOCAL';C3.installQA();C3.installGamepads()};






